package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.graphics.*;import android.widget.*;import org.json.*;import java.io.*;
final class NavigationLandmarksUi {
 static final int PHOTO=8190;final Activity host;interface Fix{android.location.Location get()throws Exception;}final Fix fixes;JSONObject photoDraft;AlertDialog photoDialog;ImageView preview;long photoGeneration;
 NavigationLandmarksUi(Activity h,Fix f){host=h;fixes=f;}
 void show(){try{JSONArray rows=NavigationLandmarks.list(host);LinearLayout root=new LinearLayout(host);root.setOrientation(1);TextView hint=new TextView(host);hint.setText("出口・駐輪場所の写真とメモを端末内へ暗号化保存します。自動撮影・外部送信・初期登録はありません。場所の検索・地図表示は、選択した場合だけ実行します。");root.addView(hint);AlertDialog[] top={null};for(int i=0;i<rows.length();i++){JSONObject item=rows.getJSONObject(i);Button button=new Button(host);button.setText(item.getString("name"));root.addView(button);button.setOnClickListener(v->{top[0].dismiss();new AlertDialog.Builder(host).setTitle(item.optString("name")).setItems(new String[]{"写真・メモを見る／編集","地図で場所を確認","削除"},(d,k)->{try{if(k==0)edit(item);else if(k==1){if(!item.has("latitude"))throw new Exception("地点は未登録です");new AlertDialog.Builder(host).setMessage("この地点を地図アプリへ渡して開きますか？ 案内は自動開始しません。").setPositiveButton("地図で確認",(a,b)->host.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("geo:"+item.optDouble("latitude")+","+item.optDouble("longitude")+"?q="+item.optDouble("latitude")+","+item.optDouble("longitude"))))).setNegativeButton("戻る",null).show();}else new AlertDialog.Builder(host).setMessage("写真・メモを含めてこの記録を削除しますか？").setPositiveButton("削除",(a,b)->{try{NavigationLandmarks.remove(host,item.getString("id"),item.getInt("revision"));show();}catch(Exception e){error(e);}}).setNegativeButton("戻る",null).show();}catch(Exception e){error(e);}}).setNegativeButton("戻る",null).show();});}Button add=new Button(host);add.setText("出口・駐輪場所を新規登録");root.addView(add);add.setOnClickListener(v->{try{top[0].dismiss();edit(new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("revision",0));}catch(Exception e){error(e);}});ScrollView scroll=new ScrollView(host);scroll.addView(root);top[0]=new AlertDialog.Builder(host).setTitle("出口・駐輪場所").setView(scroll).setNegativeButton("閉じる",null).show();}catch(Exception e){error(e);}}
 void edit(JSONObject original)throws Exception{JSONObject row=new JSONObject(original.toString());LinearLayout root=new LinearLayout(host);root.setOrientation(1);EditText name=SavedNavigationRoutesDialog.input(host,root,"名前（例：駅の出口・駐輪場所）",row.optString("name")),note=SavedNavigationRoutesDialog.input(host,root,"メモ",row.optString("note"));TextView point=new TextView(host);point.setText(row.has("latitude")?"地点登録済み":"地点未登録（写真・メモのみ保存可）");root.addView(point);Button here=new Button(host);here.setText("現在地を地点に使う");root.addView(here);here.setOnClickListener(v->{try{android.location.Location fix=fixes.get();if(fix==null||!fix.hasAccuracy()||!NavigationTurnFix.fresh(System.currentTimeMillis(),fix.getTime(),fix.getAccuracy()))throw new Exception("現在地を確認できません");row.put("latitude",fix.getLatitude()).put("longitude",fix.getLongitude());point.setText("現在地を選択済み（保存で反映）");}catch(Exception e){error(e);}});Button search=new Button(host);search.setText("地点候補を検索して選ぶ");root.addView(search);search.setOnClickListener(v->NavigationEntranceDialog.showDestination(host,name.getText().toString(),(label,address)->{try{row.put("latitude",address.getLatitude()).put("longitude",address.getLongitude());point.setText("選択地点："+label);}catch(Exception e){error(e);}}));ImageView image=new ImageView(host);image.setAdjustViewBounds(true);image.setMaxHeight(600);root.addView(image);display(image,row);Button photo=new Button(host);photo.setText("写真を選ぶ（縮小して保存）");root.addView(photo);Button clear=new Button(host);clear.setText("写真を外す");root.addView(clear);clear.setOnClickListener(v->{photoGeneration++;row.remove("photo");image.setImageDrawable(null);});ScrollView scroll=new ScrollView(host);scroll.addView(root);AlertDialog dialog=new AlertDialog.Builder(host).setTitle("出口・駐輪場所を編集").setView(scroll).setPositiveButton("暗号化して保存",null).setNegativeButton("キャンセル",null).create();photo.setOnClickListener(v->{photoGeneration++;photoDraft=row;photoDialog=dialog;preview=image;try{host.startActivityForResult(new Intent(Intent.ACTION_GET_CONTENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),PHOTO);}catch(Exception e){photoDraft=null;error(e);}});dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{row.put("name",name.getText().toString()).put("note",note.getText().toString());NavigationLandmarks.save(host,row);dialog.dismiss();show();}catch(Exception e){error(e);}});}
 void display(ImageView image,JSONObject row){if(!row.optString("photo").isEmpty()){byte[] bytes=android.util.Base64.decode(row.optString("photo"),android.util.Base64.NO_WRAP);image.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));}}
 void result(int result,Intent data){final long generation=photoGeneration;JSONObject draft=photoDraft;AlertDialog dialog=photoDialog;ImageView image=preview;photoDraft=null;photoDialog=null;preview=null;if(result!=Activity.RESULT_OK||data==null||data.getData()==null||draft==null||dialog==null||!dialog.isShowing())return;new Thread(()->{try{byte[] bytes;try(InputStream in=host.getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>8000000)throw new IOException("8MB以下の写真を選んでください");out.write(buffer,0,n);}bytes=out.toByteArray();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("写真を読み込めません");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>700)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("写真を読み込めません");ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,70,out);bitmap.recycle();if(out.size()>256000)throw new IOException("写真が大きすぎます。小さい画像を選んでください");String encoded=android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP);host.runOnUiThread(()->{if(!dialog.isShowing()||generation!=photoGeneration)return;try{draft.put("photo",encoded);display(image,draft);}catch(Exception e){error(e);}});}catch(Exception e){host.runOnUiThread(()->error(e));}},"PrivateLandmarkPhoto").start();}
 void error(Exception e){SavedNavigationRoutesDialog.error(host,e);}
}
